"""NIST ACVP ML-DSA-87 keyGen / sigGen / sigVer vectors, parsed from the generated
C header.

``hw/sys/sep/dv/fw/tests/common/abr_nist_vectors.h`` is generated by
``fw/tests/common/gen_abr_nist_vectors.py`` from the NIST ACVP-Server
internalProjection at the commit the header names. This module is the Python
golden for the no_cpu KATs; it does not re-encode the words.

The sigGen and sigVer groups are the external-mu variants (ACVP tgId 11), so a
test drives ``MLDSA_EXTERNAL_MU`` and writes mu rather than a raw message.

``NIST_SV_REJECTS`` holds every tgId 11 sigVer case with ``testPassed`` false,
each with its ACVP ``tcId`` and ``reason``. ``NIST_SV_ACCEPT`` is the accepting
case of the same group. ``NIST_SV_BAD_*`` is the tcId 151 row of the table.

These are transcribed authority values, not a recomputable construction, so
there is no independent self-test available the way ``sep_hmac_golden`` checks
itself against RFC 4231. The generated header is the vector source. Import-time
assertions check shape, non-degeneracy and table consistency only; they do not
detect a same-length transcription error.
"""

from __future__ import annotations

import re
from dataclasses import dataclass
from functools import cache
from pathlib import Path

_HEADER = Path(__file__).resolve().parents[2] / "fw" / "tests" / "common" / "abr_nist_vectors.h"


@cache
def _text(header: Path) -> str:
    return header.read_text(encoding="utf-8")


def _load_u32_array(name: str, header: Path = _HEADER) -> list[int]:
    m = re.search(
        rf"static const uint32_t {name}\[(\d+)\] = \{{(.*?)\}};",
        _text(header),
        re.S,
    )
    if not m:
        raise RuntimeError(f"{name} not found in {header}")
    words = [int(tok, 16) for tok in re.findall(r"0x([0-9a-fA-F]+)u", m.group(2))]
    n = int(m.group(1))
    if len(words) != n:
        raise RuntimeError(f"{name}: parsed {len(words)} words, header says {n}")
    return words


def _load_define(name: str, header: Path = _HEADER) -> int:
    """One ``#define <name> <int>`` from the header."""
    m = re.search(rf"^#define {name}\s+(\d+)\s*$", _text(header), re.M)
    if not m:
        raise RuntimeError(f"{name} not found in {header}")
    return int(m.group(1))


def _load_string(name: str) -> str:
    """One ``#define <name> "<text>"`` from the header."""
    m = re.search(rf'^#define {name}\s+"([^"\\]*)"\s*$', _text(_HEADER), re.M)
    if not m:
        raise RuntimeError(f"{name} not found in {_HEADER}")
    return m.group(1)


@dataclass(frozen=True)
class SigVerCase:
    """One ACVP tgId 11 sigVer case: inputs and the ACVP verdict."""

    tcid: int
    reason: str
    verdict: int
    pk: list[int]
    mu: list[int]
    sig: list[int]


# keyGen (ACVP tcId 51)
NIST_KG_SEED = _load_u32_array("nist_kg_seed")
NIST_KG_PK = _load_u32_array("nist_kg_pk")

# sigGen, deterministic + external mu (ACVP tcId 151)
NIST_SG_SK = _load_u32_array("nist_sg_sk")
NIST_SG_MU = _load_u32_array("nist_sg_mu")
NIST_SG_SIG = _load_u32_array("nist_sg_sig")

# sigVer: one case the standard says must verify (tcId 154) and one that must
# not (tcId 151). The rejecting case fails an engine that reports success
# unconditionally (VERIFY_RES equals the submitted c~ for every input).
NIST_SV_OK_PK = _load_u32_array("nist_sv_ok_pk")
NIST_SV_OK_MU = _load_u32_array("nist_sv_ok_mu")
NIST_SV_OK_SIG = _load_u32_array("nist_sv_ok_sig")
NIST_SV_OK_VERDICT = _load_define("NIST_SV_OK_VERDICT")
NIST_SV_OK_TCID = _load_define("NIST_SV_OK_TCID")

NIST_SV_BAD_PK = _load_u32_array("nist_sv_bad_pk")
NIST_SV_BAD_MU = _load_u32_array("nist_sv_bad_mu")
NIST_SV_BAD_SIG = _load_u32_array("nist_sv_bad_sig")
NIST_SV_BAD_VERDICT = _load_define("NIST_SV_BAD_VERDICT")
NIST_SV_BAD_TCID = _load_define("NIST_SV_BAD_TCID")

# The four ACVP reason classes of an ML-DSA sigVer reject case.
NIST_SV_REJECT_REASONS = (
    "modified message",
    "modified signature - commitment",
    "modified signature - hint",
    "modified signature - z",
)

NIST_SV_ACCEPT = SigVerCase(
    tcid=NIST_SV_OK_TCID,
    reason="",
    verdict=NIST_SV_OK_VERDICT,
    pk=NIST_SV_OK_PK,
    mu=NIST_SV_OK_MU,
    sig=NIST_SV_OK_SIG,
)

# Every tgId 11 sigVer reject case, in tcId order.
NIST_SV_REJECTS = [
    SigVerCase(
        tcid=_load_define(f"NIST_SV_REJ_{_k}_TCID"),
        reason=_load_string(f"NIST_SV_REJ_{_k}_REASON"),
        verdict=_load_define(f"NIST_SV_REJ_{_k}_VERDICT"),
        pk=_load_u32_array(f"nist_sv_rej_{_k}_pk"),
        mu=_load_u32_array(f"nist_sv_rej_{_k}_mu"),
        sig=_load_u32_array(f"nist_sv_rej_{_k}_sig"),
    )
    for _k in range(_load_define("NIST_SV_REJ_COUNT"))
]

# Shapes: the ML-DSA-87 word counts, mirroring the header's *_WORDS defines, so a
# header regenerated for another parameter set or a truncated array fails at import.
assert len(NIST_KG_SEED) == 8
assert len(NIST_KG_PK) == 648
assert len(NIST_SG_SK) == 1224
assert len(NIST_SG_MU) == 16
assert len(NIST_SG_SIG) == 1157
for _case in (NIST_SV_ACCEPT, *NIST_SV_REJECTS):
    assert len(_case.pk) == 648, f"tcId {_case.tcid} pk"
    assert len(_case.mu) == 16, f"tcId {_case.tcid} mu"
    assert len(_case.sig) == 1157, f"tcId {_case.tcid} sig"
assert len(NIST_SV_BAD_PK) == 648, "NIST_SV_BAD_PK"
assert len(NIST_SV_BAD_SIG) == 1157, "NIST_SV_BAD_SIG"

# Non-degeneracy: an all-zero vector would make a compare pass against a dead
# register window.
for _name, _v in (
    ("NIST_KG_SEED", NIST_KG_SEED),
    ("NIST_KG_PK", NIST_KG_PK),
    ("NIST_SG_SK", NIST_SG_SK),
    ("NIST_SG_MU", NIST_SG_MU),
    ("NIST_SG_SIG", NIST_SG_SIG),
    ("NIST_SV_OK_SIG", NIST_SV_OK_SIG),
    ("NIST_SV_BAD_SIG", NIST_SV_BAD_SIG),
    *((f"reject tcId {_c.tcid} sig", _c.sig) for _c in NIST_SV_REJECTS),
):
    assert any(w != 0 for w in _v), f"{_name} is all zero"

# The two verdicts must differ, or the accept/reject pair proves nothing.
assert NIST_SV_OK_VERDICT != NIST_SV_BAD_VERDICT, (
    "sigVer accept and reject cases carry the same verdict; the pair would not be able to fail"
)
# And the two cases must actually be different inputs.
assert NIST_SV_OK_SIG != NIST_SV_BAD_SIG or NIST_SV_OK_PK != NIST_SV_BAD_PK, (
    "sigVer accept and reject cases have identical inputs"
)

# Reject table: every row is a reject of a known class, tcIds are unique, each
# class has a row other than tcId 151, and NIST_SV_BAD_* is the tcId 151 row.
assert NIST_SV_OK_VERDICT == 1 and NIST_SV_BAD_VERDICT == 0
assert len({_c.tcid for _c in NIST_SV_REJECTS}) == len(NIST_SV_REJECTS), "duplicate tcId"
assert NIST_SV_ACCEPT.tcid not in {_c.tcid for _c in NIST_SV_REJECTS}
for _c in NIST_SV_REJECTS:
    assert _c.verdict == 0, f"reject tcId {_c.tcid} carries verdict {_c.verdict}"
    assert _c.reason in NIST_SV_REJECT_REASONS, f"reject tcId {_c.tcid} reason {_c.reason!r}"
    assert (_c.pk, _c.mu, _c.sig) != (NIST_SV_OK_PK, NIST_SV_OK_MU, NIST_SV_OK_SIG), (
        f"reject tcId {_c.tcid} has the accept case inputs"
    )
for _reason in NIST_SV_REJECT_REASONS:
    assert any(_c.reason == _reason and _c.tcid != 151 for _c in NIST_SV_REJECTS), (
        f"no reject row of class {_reason!r} other than tcId 151"
    )
_bad_rows = [_c for _c in NIST_SV_REJECTS if _c.tcid == NIST_SV_BAD_TCID]
assert NIST_SV_BAD_TCID == 151 and len(_bad_rows) == 1, "tcId 151 is not one row of the table"
assert (_bad_rows[0].pk, _bad_rows[0].mu, _bad_rows[0].sig) == (
    NIST_SV_BAD_PK,
    NIST_SV_BAD_MU,
    NIST_SV_BAD_SIG,
), "NIST_SV_BAD_* differs from the tcId 151 row of the reject table"


# sigVer cases NIST marks "modified signature - hint" (``abr_nist_hint_vectors.h``,
# ``gen_abr_nist_vectors.py --hint``), on both interfaces: pure ML-DSA with a
# context, whose message is streamed, and external mu. Case 0 is a pure case that
# must verify. The generator checks every hint case has z in range and a malformed
# hint encoding, so the core must reach the hint decode before it rejects.
_HINT_HEADER = _HEADER.with_name("abr_nist_hint_vectors.h")


class NistHintCase:
    """One sigVer case: inputs as little-endian words, byte lengths for the stream."""

    def __init__(self, i: int) -> None:
        def arr(field: str) -> list[int]:
            return _load_u32_array(f"nist_hr{i}_{field}", _HINT_HEADER)

        def define(field: str) -> int:
            return _load_define(f"NIST_HR{i}_{field}", _HINT_HEADER)

        self.tcid = define("TCID")
        self.verdict = define("VERDICT")
        self.external_mu = bool(define("EXTERNAL_MU"))
        self.pk = arr("pk")
        self.sig = arr("sig")
        if self.external_mu:
            self.mu = arr("mu")
            self.msg, self.msg_bytes, self.ctx, self.ctx_bytes = [], 0, [], 0
        else:
            self.mu = []
            self.msg, self.msg_bytes = arr("msg"), define("MSG_BYTES")
            self.ctx, self.ctx_bytes = arr("ctx"), define("CTX_BYTES")
            assert len(self.msg) == (self.msg_bytes + 3) // 4, f"tcId {self.tcid} message"
            assert len(self.ctx) == (self.ctx_bytes + 3) // 4, f"tcId {self.tcid} context"
            assert 0 < self.ctx_bytes <= 255, f"tcId {self.tcid} context length"
        assert len(self.pk) == 648 and len(self.sig) == 1157, f"tcId {self.tcid} shape"
        assert any(self.sig[:16]), f"tcId {self.tcid} c~ is all zero"

    @property
    def interface(self) -> str:
        return "external mu" if self.external_mu else "pure, context"


NIST_HINT_CASES = [NistHintCase(i) for i in range(_load_define("NIST_HR_CASES", _HINT_HEADER))]
assert NIST_HINT_CASES[0].verdict == 1 and not NIST_HINT_CASES[0].external_mu
assert all(c.verdict == 0 for c in NIST_HINT_CASES[1:])
assert {c.external_mu for c in NIST_HINT_CASES[1:]} == {False, True}
